import type {
  SearchItemsMultiCategoriesRequest,
  SearchItemsMultiCategoriesResponse,
} from '@wix/ambassador-media-public-media-v1-media-item/types';

import { SHAPE_SEARCH_ITEMS_BASE_URL } from './consts.js';

export const fetchShapes = async (
  options: SearchItemsMultiCategoriesRequest,
  makeRequest: (input: string | URL, init?: RequestInit) => Promise<Response>
): Promise<SearchItemsMultiCategoriesResponse> => {
  try {
    const response = await makeRequest(SHAPE_SEARCH_ITEMS_BASE_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(options),
    });

    return await response.json();
  } catch (error) {
    console.error('[ShapeService] Failed to fetch shapes:', error);
    throw error;
  }
};
