import { legacyPluginToNextMap } from './../ricos-schema/next-schema/plugin-names.js';
import type { EditorPlugin, EditorPluginOptions, ViewerPlugin } from './../ricos-types/index.js';

type PluginType = EditorPlugin | ViewerPlugin | EditorPluginOptions;

export const hasPlugin = (pluginType: string, plugins: PluginType[] | undefined) =>
  !!plugins?.some(
    plugin => plugin.type === pluginType || plugin.type === legacyPluginToNextMap[pluginType]
  );
