import type { GalleryData_Item } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { AnchorTarget, RelValue } from './../../ricos-types/index.js';
import { getLinkHrefUrl } from './../link/get-link-href-url.js';
import { normalizeHref } from './../link/normalize-href.js';

export type GalleryItem = {
  mediaUrl: string;
  url: string;
  metaData: {
    type: 'image' | 'video';
    title?: string;
    alt?: string;
    width: number;
    height: number;
    link?: {
      type?: string;
      target: string;
      rel?: string;
      url?: string;
      data?: {
        type: string;
        rel: string;
        url: string;
        target: string;
        anchorName?: string;
      };
    };
    poster?: {
      url: string;
      width: number;
      height: number;
    };
  };
  directLink?: {
    url: string;
    target: string;
    rel: string;
  };
  itemId: string;
  hash: string;
};

// Some items are saved with 0 (or missing) dimensions, which is invalid and breaks
// layout math (e.g. height / width division in the slider layout). Fall back to a
// sane square so the gallery can still lay the item out.
const FALLBACK_MEDIA_DIMENSION = 200;

export const convertToGalleryItem = ({
  item,
  index,
  nodeId = 'unscoped',
  relValue,
  anchorTarget,
  baseUrl,
}: {
  item: GalleryData_Item;
  index: number;
  nodeId?: string;
  relValue?: RelValue;
  anchorTarget?: AnchorTarget;
  baseUrl?: string;
}) => {
  const { image, video, title, altText } = item;
  const media = image?.media || video?.media;
  const mediaUrl = media?.src?.url || media?.src?.id || '';
  const width = media?.width || FALLBACK_MEDIA_DIMENSION;
  const height = media?.height || FALLBACK_MEDIA_DIMENSION;
  const convertedData: GalleryItem = {
    mediaUrl,
    url: mediaUrl,
    metaData: {
      type: image ? 'image' : 'video',
      height,
      width,
      title,
      alt: altText,
    },
    itemId: `gallery-item:${nodeId}:${index}`,
    hash: mediaUrl + '_' + index.toString(),
  };
  if (video) {
    convertedData.metaData.link = {
      target: '_blank',
      rel: 'noopener',
      url: normalizeHref(mediaUrl) ?? '',
    };
    const { src, width: thumbnailWidth, height: thumbnailHeight } = video.thumbnail || {};
    if (src?.url || src?.id) {
      convertedData.metaData.poster = {
        url: src.url || src.id || '',
        width: thumbnailWidth || width,
        height: thumbnailHeight || height,
      };
    }
  }
  if (image?.link) {
    const { url: linkUrl = '', target: linkTarget, rel: linkRel, anchor } = image.link;

    const target = (linkTarget && `_${linkTarget.toLowerCase()}`) || anchorTarget || '_self';
    let rel = relValue || 'noopener';

    if (linkRel) {
      rel = 'noopener';
      linkRel.nofollow && (rel += ' nofollow');
      linkRel.sponsored && (rel += ' sponsored');
      linkRel.ugc && (rel += ' ugc');
      (linkRel.noreferrer || linkRel.noreferrer === undefined) && (rel += ' noreferrer');
    }

    const normalizedUrl = normalizeHref(linkUrl) ?? '';

    const url = normalizedUrl
      ? normalizedUrl
      : (getLinkHrefUrl(anchor ? { anchor } : { url: linkUrl }, baseUrl) ?? '');

    convertedData.metaData.link = {
      type: 'wix',
      target,
      data: {
        type: anchor ? 'AnchorLink' : 'ExternalLink',
        target,
        rel,
        url,
        anchorName: anchor,
      },
    };

    convertedData.directLink = {
      url,
      target,
      rel,
    };
  }
  return convertedData;
};
