import { Box, CloseButton, Image, Loader, StatusIndicator, Text } from '@wix/design-system';
import { DataCollection, Document } from '@wix/wix-ui-icons-common/lazy';
import classNames from 'classnames';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { unreachable } from './../../uncreachable.js';

import type { Attachment } from '../../pm-node-types.js';
import classes from './attachment-bar-scss.js';

const resolveImageUrl = (url: string): string => {
  if (url.startsWith('http://') || url.startsWith('https://')) {
    return url;
  }

  const mediaId = url.startsWith('media/') ? url : `media/${url}`;
  return `https://static.wixstatic.com/${mediaId}`;
};

export const AttachmentBar: React.FC<{
  attachments: Attachment[];
  onRemove: (id: string) => void;
}> = ({ attachments, onRemove }) => {
  return (
    <div className={classes.root}>
      {attachments.map(attachment =>
        ['png', 'jpg', 'jpeg'].includes(attachment.file.type) ? (
          <ImageAttachment key={attachment.id} attachment={attachment} onRemove={onRemove} />
        ) : (
          <FileAttachment key={attachment.id} attachment={attachment} onRemove={onRemove} />
        )
      )}
    </div>
  );
};

const ImageAttachment: React.FC<{ attachment: Attachment; onRemove: (id: string) => void }> = ({
  attachment,
  onRemove,
}) => {
  const { t } = useContext(RicosContext);
  return (
    <div className={classes.attachmentWrapper}>
      {(() => {
        switch (attachment.status) {
          case 'ok': {
            return (
              <Image
                src={resolveImageUrl(attachment.file.url)}
                showBorder
                width={48}
                height="100%"
              />
            );
          }

          case 'loading': {
            return (
              <div className={classes.statusIconContainer}>
                <Loader size="tiny" />
              </div>
            );
          }

          case 'error': {
            return (
              <div className={classes.statusIconContainer}>
                <StatusIndicator
                  status="error"
                  message={attachment.error}
                  tooltipProps={{ enterDelay: 300 }}
                />
              </div>
            );
          }
          default:
            return null;
        }
      })()}
      <RemoveButton
        label={t('HtmlPlugin_AiWidget_Remove_Image_Attachment_Button_AriaLabel')}
        onRemove={() => onRemove(attachment.id)}
      />
    </div>
  );
};

const FileAttachment: React.FC<{
  attachment: Attachment;
  onRemove: (id: string) => void;
}> = ({ attachment, onRemove }) => {
  const { t } = useContext(RicosContext);
  const { name, type } = attachment.file;

  const getAttachmentIcon = (fileType: 'csv' | 'text' | (string & {})) => {
    switch (fileType) {
      case 'csv':
        return <DataCollection color="#fff" />;
      case 'pdf':
        return <Document color="#fff" />;
      case 'text':
      default:
        return <Document color="#000" />;
    }
  };

  const getIconBackground = () => {
    switch (attachment.status) {
      case 'ok':
        if (type === 'csv') {
          return '#25A55A';
        }
        if (type === 'pdf') {
          return '#E62214';
        }
        return '#ECEFF3';
      case 'loading':
        return '#ECEFF3';
      case 'error':
        return '#fde3e1';
      default:
        unreachable(attachment);
        return null;
    }
  };

  return (
    <div className={classes.attachmentWrapper}>
      <div
        className={classNames(classes.fileAttachment, {
          [classes.error]: attachment.status === 'error',
        })}
        style={
          {
            '--ricos-internal-file-attachment-background-color': getIconBackground(),
          } as React.CSSProperties
        }
      >
        <div className={classes.fileAttacmentIcon}>
          {(() => {
            switch (attachment.status) {
              case 'ok':
                return getAttachmentIcon(type);
              case 'loading':
                return <Loader size="tiny" />;
              case 'error':
                return (
                  <StatusIndicator
                    status="error"
                    message={attachment.error}
                    tooltipProps={{ enterDelay: 300 }}
                  />
                );
              default:
                unreachable(attachment);
                return null;
            }
          })()}
        </div>
        <Box direction="vertical" width={137}>
          <Text size="small" weight="normal" ellipsis enterDelay={300}>
            {name}
          </Text>
          <Text
            size="tiny"
            weight="thin"
            ellipsis
            enterDelay={300}
            skin={attachment.status === 'error' ? 'error' : undefined}
          >
            {(() => {
              switch (attachment.status) {
                case 'ok':
                case 'loading':
                  return type.toUpperCase();
                case 'error':
                  return t('UploadFile_Error_Generic_Toast');
                default:
                  unreachable(attachment);
                  return null;
              }
            })()}
          </Text>
        </Box>
      </div>
      <RemoveButton
        label={t('HtmlPlugin_AiWidget_Remove_Attachment_Button_AriaLabel', { fileName: name })}
        onRemove={() => onRemove(attachment.id)}
      />
    </div>
  );
};

const RemoveButton: React.FC<{ label: string; onRemove: () => void }> = ({ label, onRemove }) => (
  <div className={classes.removeButton}>
    <CloseButton aria-label={label} size="small" skin="standardFilled" onClick={onRemove} />
  </div>
);
