import type { BackgroundImage } from './../ricos-schema/next-schema/index.js';
import type { Gradient } from './../ricos-types/color-palette-types.js';

import { resolveBackwardCompatOverlay } from './resolve-backward-compat-overlay.js';

export type ResolvedImageOverlay = { color?: string; gradient?: Gradient };

/**
 * Resolves the color/gradient overlay drawn on top of a background image,
 * bridging the old and new models.
 *
 * The presence of `image.overlay` is the unambiguous new-model marker: old
 * content can never have it. When present it is authoritative and `opacity` is
 * ignored. When absent we fall back to the legacy fill + `opacity` dimming via
 * `resolveBackwardCompatOverlay` (gradients were never affected by `opacity`,
 * matching the previous behaviour).
 */
export function resolveImageOverlay(
  image: BackgroundImage | undefined,
  legacy: { gradient?: Gradient; color?: string },
  opacityMax: 1 | 100 = 100
): ResolvedImageOverlay | undefined {
  if (!image) {
    return undefined;
  }
  if (image.overlay) {
    return image.overlay.type === 'GRADIENT'
      ? { gradient: image.overlay.gradient }
      : { color: image.overlay.color };
  }
  if (legacy.gradient) {
    return { gradient: legacy.gradient };
  }
  if (legacy.color !== undefined) {
    return {
      color: resolveBackwardCompatOverlay(legacy.color, image.opacity ?? opacityMax, opacityMax),
    };
  }
  return undefined;
}
