import React, { useContext, useEffect, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { useModalService } from './../../ricos-modals/index.js';
import type { IToolbarItem, ToolbarButton } from './../../ricos-types/index.js';
import type { ToolbarButtonCommand } from './../../ricos-types/plugin-types.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';

import { PLUGIN_TOOLBAR_COLOR_BUTTON } from '../data-hooks.js';
import { getNodeInSelection } from '../resolvers/get-node-in-selection.js';
import { ToolbarButton as ToolbarButtonComponent } from '../toolbar-button/toolbar-button.js';
import { ColorSwatch } from './color-swatch.js';
import { PLUGIN_TOOLBAR_BUTTON_ID } from './plugin-toolbar-buttons-ids.js';

type ColorButtonOptions = {
  command: ToolbarButtonCommand;
  dataHook?: string;
  buttonId?: string;
  modalId?: string;
  getColors: (selectedNode: PmNode) => string[];
  tooltip?: string;
};

export const createColorButton = ({
  command,
  dataHook,
  buttonId,
  modalId,
  getColors,
}: ColorButtonOptions): ToolbarButton => {
  return {
    id: buttonId ?? PLUGIN_TOOLBAR_BUTTON_ID.COLOR,
    type: 'color',
    attributes: {
      selectedNode: getNodeInSelection,
      active: (_, { modals }) => (modalId ? !!modals?.getModal(modalId) : false),
    },
    tooltip: 'ColorButton_Tooltip',
    dataHook: dataHook ?? PLUGIN_TOOLBAR_COLOR_BUTTON,
    renderer: toolbarItem => (
      <ToolbarColorButton dataHook={dataHook} toolbarItem={toolbarItem} getColors={getColors} />
    ),
    getComponentProps: ({ attributes }) => ({
      colors: attributes.selectedNode ? getColors(attributes.selectedNode) : [],
    }),
    command,
  };
};

const ToolbarColorButton = ({
  toolbarItem,
  dataHook,
  getColors,
}: {
  toolbarItem: IToolbarItem;
  dataHook?: string;
  getColors: (selectedNode: PmNode) => string[];
}) => {
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const [isActive, setIsActive] = useState(toolbarItem.attributes.active);
  const { isMobile, t } = useContext(RicosContext) || {};
  const modalService = useModalService();
  const onClick = toolbarItem.commands.click;

  useEffect(() => {
    modalService.onModalOpened(() => {
      setIsActive(!!toolbarItem.attributes.active);
    });

    modalService.onModalClosed(() => {
      setIsActive(!!toolbarItem.attributes.active);
    });
  }, [modalService]);

  const resolvedColors = toolbarItem.attributes.selectedNode
    ? getColors(toolbarItem.attributes.selectedNode)
    : [];

  return (
    <ToolbarButtonComponent
      prefix={() => <ColorSwatch colors={resolvedColors} />}
      active={isActive}
      onClick={() => onClick({ isMobile, referenceElement })}
      dataHook={dataHook}
      tooltip={t('ColourButton_Tooltip')}
      ariaLabel={t('ColourButton_Tooltip')}
      ref={setReferenceElement}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
