import type { DefaultBIParams } from './../ricos-common/ricos-types.js';

import { deepMerge } from './deep-merge.js';

interface Args extends DefaultBIParams {
  platformAPIs?: any;
  bi?: any;
  biLogger?: any;
  biLoggerFactory?: any;
}

function callFunctions(obj: any) {
  if (typeof obj === 'function') {
    return obj();
  }
  return obj;
}

function resolveValues(obj: Record<string, any>): any {
  return Object.entries(obj).reduce(
    (acc, curr) => ({
      ...acc,
      [curr[1] && curr[0]]: callFunctions(curr[1]),
    }),
    {}
  );
}

function getCommonFields(obj?: any): DefaultBIParams {
  if (!obj || Object.keys(obj).length === 0) {
    return {};
  }
  const {
    bsi,
    metaSiteId,
    visitorId,
    visitor_id, // (visitorId) multiple variations, same value
    _appId,
    _instanceId,
    _msid, // (metaSiteId) multiple variations, same value
    _siteOwnerId,
  } = resolveValues(obj);
  return Object.fromEntries(
    Object.entries({
      bsi,
      visitorId: visitor_id || visitorId,
      appId: _appId,
      instanceId: _instanceId,
      metaSiteId: _msid || metaSiteId,
      siteOwnerId: _siteOwnerId,
    }).filter(([, value]) => !!value)
  );
}

function fromBiLoggerFactory(biLoggerFactory?: Args['biLoggerFactory']): DefaultBIParams {
  const obj = deepMerge(
    {},
    biLoggerFactory?.()?.loggerClientFactory?._defaults,
    biLoggerFactory?.()?.loggerClientFactory?._nonEssentialDefaults
  );
  return getCommonFields(obj);
}

function fromBiObject(bi?: Args['bi']): DefaultBIParams {
  return getCommonFields(bi);
}

function fromBiLogger(biLogger?: Args['biLogger']): DefaultBIParams {
  const obj = biLogger?.biLoggerClientFactoryInstance?.loggerClientFactory?._defaults;
  return getCommonFields(obj);
}

/**
 * Extracts essential BI fields for WixRicos' `BISettings`.
 *
 * Make sure to supply a combination of the following params, in any way you wish, that will
 * supply the following fields: `bsi`, `metaSiteId`, `visitorId`.
 *
 * You can provide them explicitly if you wish.
 * @param bi - contains `metaSiteId`, `visitorId`
 * @param biLogger - contains `bsi`, `_msid`, `visitor_id`
 * @param biLoggerFactory - contains `bsi`, `_msid`
 * @param platformAPIs - contains `biLogger` and `biLoggerFactory`
 * @returns Essential BI fields
 */
export const extractUoUParams = ({
  bi,
  biLogger,
  biLoggerFactory,
  platformAPIs,
}: Args = {}): DefaultBIParams => {
  return deepMerge(
    fromBiObject(bi || platformAPIs?.bi),
    fromBiLogger(biLogger),
    fromBiLoggerFactory(biLoggerFactory || platformAPIs?.biLoggerFactory)
  );
};
