export type ObjectPath = PropertyKey | readonly PropertyKey[];

// Path segments that must never be traversed/written — blocking them prevents
// prototype pollution when a path comes from untrusted input.
export const UNSAFE_PATH_KEYS: readonly PropertyKey[] = ['__proto__', 'constructor', 'prototype'];

export const hasUnsafePathSegment = (segments: readonly PropertyKey[]): boolean =>
  segments.some(segment => UNSAFE_PATH_KEYS.includes(segment));

// Normalizes a lodash-style object path (array of keys or an 'a.b[0].c' string)
// into individual segments. Numeric segments from a string path are returned as
// numbers so consumers can create array containers (matching lodash.set), e.g.
// 'a[0].b' -> ['a', 0, 'b'].
export function pathToSegments(path: ObjectPath): PropertyKey[] {
  if (Array.isArray(path)) {
    return [...path];
  }
  if (typeof path === 'string') {
    return path
      .replace(/\[(\d+)\]/g, '.$1')
      .split('.')
      .filter(segment => segment !== '')
      .map(segment => (/^\d+$/.test(segment) ? Number(segment) : segment));
  }
  return [path as PropertyKey];
}
