import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Resolver } from './../../ricos-types/index.js';

const headingMap = {
  1: 'header-one',
  2: 'header-two',
  3: 'header-three',
  4: 'header-four',
  5: 'header-five',
  6: 'header-six',
} as const;

type HeadingInSelectionValue = 'unstyled' | (typeof headingMap)[keyof typeof headingMap];

export const getHeadingInSelection: Resolver<HeadingInSelectionValue | undefined> = (
  content,
  _services,
  _editor
) => {
  if (Array.isArray(content) && content.length > 0) {
    const headingLevel = content.find(node => node.type.name === Node_Type.HEADING)?.attrs?.level;
    if (!headingLevel || content[0].type.name === Node_Type.PARAGRAPH) {
      return 'unstyled';
    }
    return headingMap[headingLevel as keyof typeof headingMap];
  }
  return undefined;
};
