import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const isCodeBlockInSelection: Resolver<boolean> = content => {
  return (
    Array.isArray(content) && content.length > 0 && content[0].type.name === Node_Type.CODE_BLOCK
  );
};
