import { useCallback } from 'react';
import { useSyncExternalStore } from 'use-sync-external-store/shim';

import type { Editor } from './../../tiptap/react/index.js';

/**
 * Scoped per editor instance (not a single global flag) so that multiple Ricos
 * editors mounted on one page never freeze each other's toolbars.
 */
const records = new WeakMap<Editor, { playing: boolean; listeners: Set<() => void> }>();

const getRecord = (editor: Editor) => {
  let record = records.get(editor);
  if (!record) {
    record = { playing: false, listeners: new Set() };
    records.set(editor, record);
  }
  return record;
};

/**
 * Marks whether a `@wix/motion` entrance/loop preview is currently playing on
 * `editor`'s canvas. Floating toolbars read this (via `useIsAnimationPreviewing`)
 * to pause their floating-ui `autoUpdate` tracking while the preview runs — they
 * stay visible, but repositioning every frame would chase the animating node's
 * bounding rect.
 */
export const setAnimationPreviewing = (
  editor: Editor | null | undefined,
  playing: boolean
): void => {
  if (!editor) {
    return;
  }
  const record = getRecord(editor);
  if (record.playing === playing) {
    return;
  }
  record.playing = playing;
  record.listeners.forEach(listener => listener());
};

/**
 * Accepts a missing editor (returning false) so callers can read straight off a context whose
 * default is null — a WeakMap rejects a non-object key outright, so an unguarded call would throw
 * rather than degrade.
 */
export const useIsAnimationPreviewing = (editor: Editor | null | undefined): boolean => {
  // both callbacks stay stable across renders: a fresh `subscribe` identity makes
  // useSyncExternalStore tear the listener down and re-add it on every render, and
  // floating toolbars (the only consumer) re-render constantly. getRecord is called
  // inside them rather than during render so nothing mutates the WeakMap while rendering.
  const subscribe = useCallback(
    (listener: () => void) => {
      if (!editor) {
        return () => {};
      }
      const { listeners } = getRecord(editor);
      listeners.add(listener);
      return () => void listeners.delete(listener);
    },
    [editor]
  );
  const getSnapshot = useCallback(() => Boolean(editor && getRecord(editor).playing), [editor]);
  return useSyncExternalStore(subscribe, getSnapshot);
};
