import type { Animation, Node as RicosDocumentNode } from './../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';
import { toCamelCase } from './../to-camel-case.js';

// Node_Type is a closed enum, so the payload key is resolved once per type instead of
// once per call — this runs for every node in hasAnimatedNodes (a full-tree walk), in
// collectAnimations, and in AnimationDecorator.rule (every node, every viewer render).
const DATA_FIELD_BY_TYPE: Record<string, string> = Object.fromEntries(
  Object.values(Node_Type).map(type => [type, `${toCamelCase(type)}Data`])
);

/**
 * Uniform read of a node's animation across all animatable node types —
 * animation lives inside each node's data payload (`imageData.animation`,
 * `paragraphData.animation`, ...), never on the node itself.
 */
export const getNodeAnimation = (node: RicosDocumentNode): Animation | undefined => {
  const dataField = DATA_FIELD_BY_TYPE[node.type];
  if (!dataField) {
    return undefined;
  }
  const data = node[dataField as keyof RicosDocumentNode];
  return (data as { animation?: Animation } | undefined)?.animation;
};
