import { splitWords } from './split-words.js';

// lodash.snakeCase for the ASCII identifiers ricos converts:
// 'linkPreview' → 'link_preview', 'configButtonId' → 'config_button_id'.
export function toSnakeCase(str: string | undefined): string {
  return splitWords(str ?? '')
    .map(word => word.toLowerCase())
    .join('_');
}
