import type { IEditorQuery } from './../../ricos-content-query/index.js';
import { Decoration_Type } from './../../ricos-types/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const isSpoilerInText: Resolver<boolean> = (content, { getEditorQuery }, _editor) => {
  const editorQuery: IEditorQuery = getEditorQuery();
  const decorations = editorQuery.query.activeDecorationsByType(Decoration_Type.SPOILER);
  return (
    decorations.length > 0 &&
    decorations.every((item: $TSFixMe) => item?.type === Decoration_Type.SPOILER)
  );
};
