import type { GalleryData_Item } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { AnchorTarget, RelValue } from './../../ricos-types/index.js';

import type { GalleryItem } from './convert-to-gallery-item.js';
import { convertToGalleryItem } from './convert-to-gallery-item.js';

export const convertToGalleryItemList = ({
  items,
  nodeId,
  relValue,
  anchorTarget,
  baseUrl,
}: {
  items: GalleryData_Item[];
  nodeId?: string;
  relValue?: RelValue;
  anchorTarget?: AnchorTarget;
  baseUrl?: string;
}): GalleryItem[] => {
  return items.map((item, index) =>
    convertToGalleryItem({ item, index, nodeId, relValue, anchorTarget, baseUrl })
  );
};
