import type { ObjectPath } from './path-to-segments.js';
import { hasUnsafePathSegment, pathToSegments } from './path-to-segments.js';

// Writes a nested value by a lodash-style path (array of keys or 'a.b[0].c'
// string), creating intermediate objects/arrays like lodash.set (a numeric next
// segment creates an array). Mutates and returns `obj`. Paths containing unsafe
// keys (__proto__/constructor/prototype) are rejected to prevent prototype
// pollution when the path originates from untrusted input (e.g. translatables).
export function setByPath<T extends object>(obj: T, path: ObjectPath, value: unknown): T {
  const segments = pathToSegments(path);
  if (hasUnsafePathSegment(segments)) {
    return obj;
  }
  let current = obj as Record<PropertyKey, unknown>;
  segments.forEach((segment, i) => {
    if (i === segments.length - 1) {
      current[segment] = value;
      return;
    }
    const next = current[segment];
    if (typeof next !== 'object' || next === null) {
      const nextSegment = segments[i + 1];
      current[segment] = typeof nextSegment === 'number' ? [] : {};
    }
    current = current[segment] as Record<PropertyKey, unknown>;
  });
  return obj;
}
