import type { ImageComponentData, UpdateEntityFileSelectFunc } from './../../ricos-content/index.js';
import type { RicosServices } from './../../ricos-types/index.js';

import { createOpenMediaManagerFn } from './create-open-media-manager-fn.js';
import { MediaManagerMediaType } from './types.js';

export const createImageFileSelectionFn = (
  services: Pick<RicosServices, 'wixInstance' | 'modals'>
) => {
  const openMediaManager = createOpenMediaManagerFn(services.modals);
  if (!openMediaManager) {
    return undefined;
  }

  return (
    updateEntity: UpdateEntityFileSelectFunc<ImageComponentData[]>,
    options: { index: number | undefined; multiple: boolean },
    onCancel: () => void
  ) =>
    openMediaManager({
      mediaType: MediaManagerMediaType.IMAGE,
      appDefId: services.wixInstance().appDefId,
      isMultiSelect: options.multiple,
    })
      .then(items => {
        const imageData = items.map(
          ({
            title,
            uri,
            height,
            width,
          }: {
            title: string;
            uri: string;
            height: number;
            width: number;
          }) => ({
            id: uri,
            height,
            width,
            original_file_name: title,
            file_name: uri,
          })
        );

        updateEntity({
          data: imageData,
          // @ts-expect-error
          index: options.index,
        });
      })
      .catch(onCancel);
};
