import { Box, Text } from '@wix/design-system';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';

import { ICONS_CATEGORY_ID, SHAPES_CATEGORY_ID } from './consts.js';
import type { ShapesCategoryId } from './types.js';

export const ShapeSelectEmpty = ({
  isError,
  selectedCategoryId,
}: {
  isError?: boolean;
  selectedCategoryId: ShapesCategoryId;
}) => {
  const { t } = useContext(RicosContext);

  const isShapesCategory = selectedCategoryId === SHAPES_CATEGORY_ID;
  const isIconsCategory = selectedCategoryId === ICONS_CATEGORY_ID;

  const getEmptyStateTitle = () => {
    if (isError) {
      return isShapesCategory
        ? t('ShapeSelectModalContent_Search_ErrorState_Title')
        : isIconsCategory
          ? t('ShapeSelectModalContent_Search_ErrorState_Title_Icons')
          : t('ShapeSelectModalContent_Search_ErrorState_Title_VectorArt');
    }

    return isShapesCategory
      ? t('ShapeSelectModalContent_Search_EmptyState_Title')
      : isIconsCategory
        ? t('ShapeSelectModalContent_Search_EmptyState_Title_Icons')
        : t('ShapeSelectModalContent_Search_EmptyState_Title_VectorArt');
  };

  return (
    <Box
      height="100%"
      alignContent="center"
      display="grid"
      textAlign="center"
      fontSize="14px"
      letterSpacing="1px"
      gap="12px"
    >
      <Text size="medium" weight="bold">
        {getEmptyStateTitle()}
      </Text>
      <Text size="small" weight="thin">
        {isError
          ? t('ShapeSelectModalContent_Search_ErrorState_Text')
          : t('ShapeSelectModalContent_Search_EmptyState_Text')}
      </Text>
    </Box>
  );
};
