import { CHECKBOX_LIST_STYLE_ATTRIBUTE_VALUE } from './checkbox-list-style.js';

/**
 * Detects whether a `<ul>` element represents a checkbox list.
 *
 * Recognizes both Ricos's own markup (`data-list-style="checkbox"`) and
 * Google-Docs-style checklists, whose items are `<li role="checkbox" aria-checked="…">`
 * inside a plain `<ul>` with no `data-list-style`. Only DIRECT-child `<li>`s are
 * inspected so a regular list that merely contains a nested checkbox list is not
 * misclassified.
 */
export const isCheckboxListElement = (element: Element): boolean =>
  element.getAttribute('data-list-style')?.toLowerCase() === CHECKBOX_LIST_STYLE_ATTRIBUTE_VALUE ||
  Array.from(element.children).some(
    child =>
      child.tagName === 'LI' &&
      (child.getAttribute('role') === 'checkbox' || child.hasAttribute('aria-checked'))
  );
