import type { LinkData } from './../../ricos-schema/next-schema/index.js';
import { Decoration_Type } from './../../ricos-types/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const getUrlLinkData: Resolver<LinkData | boolean> = content => {
  if (Array.isArray(content)) {
    const node = content.find(node => node.type.name === 'text');
    if (node?.marks.some(mark => mark.type.name === Decoration_Type.LINK)) {
      return node.marks[0].attrs.link;
    }
  }
  return false;
};
