import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Node as PmNode } from './../tiptap/pm/model.js';

import { TOP_LEVEL_NODES } from './top-level-nodes.js';

const isEmptyTextNode = (node: PmNode): boolean =>
  (node.type.name === Node_Type.PARAGRAPH || node.type.name === Node_Type.HEADING) &&
  node.childCount === 0;

export const getIsEditorEmpty = (doc: PmNode): boolean => {
  const { firstChild } = doc;

  if (doc.childCount !== 1 || !firstChild) {
    return false;
  }

  // Walk through wrapper nodes (CARD → CARD_CONTENT → …) until we reach the
  // actual content block. At each level the wrapper must hold exactly one child
  // for the editor to be considered empty.
  let current: PmNode | null = firstChild;
  while (current && (TOP_LEVEL_NODES as readonly string[]).includes(current.type.name)) {
    if (current.childCount !== 1 || !current.firstChild) {
      return false;
    }
    current = current.firstChild;
  }

  return !!current && isEmptyTextNode(current);
};
