// Plain data objects, including null-prototype ones (ProseMirror builds attrs
// with Object.create(null)); restricting to Object.prototype would return those
// by reference instead of cloning them.
const isPlainObject = (value: unknown): value is Record<string, unknown> => {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
};

// Deep-clones the JSON-like structures ricos passes around (content, plugin
// data, poll state). Arrays and plain objects are cloned recursively; anything
// else (functions, class instances) is returned by reference, which is safe for
// our data and avoids structuredClone's browser-support and DataCloneError
// pitfalls.
export function cloneDeep<T>(value: T): T {
  if (Array.isArray(value)) {
    return value.map(cloneDeep) as T;
  }
  if (value instanceof Date) {
    return new Date(value.getTime()) as T;
  }
  if (isPlainObject(value)) {
    // Preserve the prototype (Object.prototype or null) so a null-proto source
    // clones into a null-proto object, matching lodash.cloneDeep.
    const clone = Object.create(Object.getPrototypeOf(value)) as Record<string, unknown>;
    for (const key of Object.keys(value)) {
      clone[key] = cloneDeep(value[key]);
    }
    return clone as T;
  }
  return value;
}
