import type { Editor } from './../../tiptap/core/index.js';

import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';

type ListType = Node_Type.BULLETED_LIST | Node_Type.ORDERED_LIST | Node_Type.CHECKBOX_LIST;

const LIST_TYPES: ReadonlySet<string> = new Set([
  Node_Type.BULLETED_LIST,
  Node_Type.ORDERED_LIST,
  Node_Type.CHECKBOX_LIST,
]);

const isListType = (name: string): name is ListType => LIST_TYPES.has(name);

export const resolveListTypeInSelection = (editor: Editor | undefined): ListType | undefined => {
  if (!editor?.state) {
    return undefined;
  }

  const { $from, $to } = editor.state.selection;
  const sharedDepth = $from.sharedDepth($to.pos);
  const commonAncestor = $from.node(sharedDepth);
  const fromIndex = $from.index(sharedDepth);
  const toIndex = $to.indexAfter(sharedDepth);

  const children = Array.from({ length: toIndex - fromIndex }, (_, i) =>
    commonAncestor.child(fromIndex + i)
  );
  const firstListIndex = children.findIndex(child => isListType(child.type.name));

  if (firstListIndex !== -1) {
    const firstListType = children[firstListIndex].type.name as ListType;
    const allMatch = children
      .slice(firstListIndex)
      .every(child => isListType(child.type.name) && child.type.name === firstListType);
    return allMatch ? firstListType : undefined;
  }

  const depths = Array.from({ length: sharedDepth + 1 }, (_, i) => sharedDepth - i);
  const listDepth = depths.find(d => isListType($from.node(d).type.name));

  return listDepth !== undefined ? ($from.node(listDepth).type.name as ListType) : undefined;
};
