import { Node_Type, type Resolver } from './../../ricos-types/index.js';

export const getLinkPreviewLinkData: Resolver<string | undefined> = (
  content,
  _services,
  _editor
) => {
  if (Array.isArray(content)) {
    const node = content.find(node => {
      return node.type.name === Node_Type.LINK_PREVIEW;
    });
    return node?.attrs.link;
  }
  return undefined;
};
