import type { ReferenceType } from '@floating-ui/react-dom';
import { autoUpdate } from '@floating-ui/react-dom';
import { useContext, useEffect } from 'react';

import { EditorContext } from './../../ricos-context/index.js';

import { useIsAnimationPreviewing } from './animation-preview-signal.js';

/**
 * Runs floating-ui's `autoUpdate` position tracking, pausing it while a `@wix/motion`
 * preview plays on the referenced node. Tracking lives in an effect rather than in
 * `whileElementsMounted` so it can pause — the floating element stays visible, but
 * repositioning per frame would chase the animating node's bounding rect. Re-attaching
 * on resume fires an immediate update, so any drift accumulated during the preview
 * (e.g. the user scrolled) is corrected the moment it ends.
 */
export const useAnimationPausedAutoUpdate = ({
  reference,
  floating,
  update,
}: {
  reference: ReferenceType | null;
  floating: HTMLElement | null;
  update: () => void;
}): void => {
  // optional all the way down: EditorContext's default value is null, so a consumer
  // rendered outside the provider must degrade to plain tracking, not throw
  const editorContext = useContext(EditorContext);
  const isAnimationPreviewing = useIsAnimationPreviewing(editorContext?.adapter?.tiptapEditor);

  useEffect(() => {
    if (isAnimationPreviewing || !reference || !floating) {
      return;
    }
    return autoUpdate(reference, floating, update, {
      animationFrame: true, // this fix issue of reposition when scrolling
    });
  }, [isAnimationPreviewing, reference, floating, update]);
};
