import type { CSSProperties, ReactNode } from 'react';
import React, { useEffect, useRef } from 'react';
import ReactDOM from 'react-dom';

import { FocusManager } from './/focus-manager/focus-manager.js';

// Stable per-instance id without `useId` (React 18-only; we stay React 16 compatible).
let viewerModalCounter = 0;

type ViewerModalProps = {
  isOpen: boolean;
  onRequestClose: () => void;
  className?: string;
  overlayClassName?: string;
  style?: { overlay?: CSSProperties; content?: CSSProperties };
  /** Portal target. Defaults to `document.body`. */
  container?: HTMLElement | (() => HTMLElement | null);
  contentLabel?: string;
  children: ReactNode;
};

const defaultContainer = () => (typeof document !== 'undefined' ? document.body : null);

/**
 * A dependency-free modal for the viewer, where the editor's modal service is
 * not mounted. Portals an overlay + focus-trapped content to `document.body`,
 * locks background scroll, and closes on Escape or overlay click. The content
 * element is the focus-trap container itself, so no extra wrapper elements are
 * introduced (preserving the consumer's layout). Replaces `react-modal`.
 */
export const ViewerModal = ({
  isOpen,
  onRequestClose,
  className,
  overlayClassName,
  style,
  container = defaultContainer,
  contentLabel,
  children,
}: ViewerModalProps) => {
  const contentIdRef = useRef<string>();
  if (!contentIdRef.current) {
    viewerModalCounter += 1;
    contentIdRef.current = `ricos-viewer-modal-${viewerModalCounter}`;
  }
  const contentId = contentIdRef.current;

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    // Lock background scroll while the modal is open (react-modal did this).
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onRequestClose();
      }
    };
    document.addEventListener('keydown', onKeyDown);

    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [isOpen, onRequestClose]);

  if (!isOpen) {
    return null;
  }

  const target = typeof container === 'function' ? container() : container;
  if (!target) {
    return null;
  }

  const modal = (
    <div
      className={overlayClassName}
      style={style?.overlay}
      // close when the overlay itself (not its content) is clicked
      onClick={event => event.target === event.currentTarget && onRequestClose()}
    >
      <FocusManager
        id={contentId}
        className={className}
        style={style?.content}
        role="dialog"
        aria-modal="true"
        aria-label={contentLabel}
        // The dialog is programmatically focusable so the focus-trap has a
        // target even when the content has no tabbable node.
        tabIndex={-1}
        focusTrapOptions={{
          fallbackFocus: () => document.getElementById(contentId) as HTMLElement,
        }}
      >
        {children}
      </FocusManager>
    </div>
  );

  return ReactDOM.createPortal(modal, target);
};
