import { Tooltip } from '@wix/design-system';
import { EditSmall } from '@wix/wix-ui-icons-common/lazy';
import cx from 'classnames';
import React, { forwardRef, useContext, useEffect, useRef, useState } from 'react';

import { ADD_CAPTION_BUTTON } from './../../plugin-figure/data-hooks.js';
import { RicosContext } from './../../ricos-context/index.js';

import classes from './add-caption-button-scss.js';

type AddCaptionButtonProps = {
  onAddCaption: () => void;
  containerRef?: React.RefObject<HTMLElement>;
};

type ButtonMode = 'full' | 'icon-only' | 'hidden';

type CaptionButtonContentProps = {
  onAddCaption?: () => void;
  isIconOnly: boolean;
};

const CaptionButtonContent = forwardRef<HTMLButtonElement, CaptionButtonContentProps>(
  ({ onAddCaption, isIconOnly }, ref) => {
    const { t, isMobile } = useContext(RicosContext);

    const handleClick = (e: React.MouseEvent | React.TouchEvent) => {
      e.preventDefault();
      e.stopPropagation();
      onAddCaption?.();
    };

    return (
      <button
        ref={ref}
        className={cx(classes.addCaptionButton, {
          [classes.mobile]: isMobile,
          [classes.withIcon]: isIconOnly,
          [classes.iconOnly]: isIconOnly,
        })}
        onClick={handleClick}
        onMouseDown={e => {
          e.preventDefault();
          e.stopPropagation();
        }}
        // Handle touch events for mobile Safari iframe
        onTouchEnd={isMobile ? handleClick : undefined}
        data-hook={ADD_CAPTION_BUTTON}
        type="button"
        aria-label={t('Figure_Caption_AddButton_AriaLabel')}
      >
        <EditSmall className={classes.icon} />
        {!isIconOnly && t('Figure_Caption_AddButton_Title')}
      </button>
    );
  }
);

export const AddCaptionButton: React.FC<AddCaptionButtonProps> = ({
  onAddCaption,
  containerRef,
}) => {
  const { t, jsdomMode } = useContext(RicosContext);
  const [buttonMode, setButtonMode] = useState<ButtonMode>(() => (jsdomMode ? 'full' : 'hidden'));
  const [dimensions, setDimensions] = useState<{ fullWidth: number; iconWidth: number } | null>(
    null
  );
  const buttonRef = useRef<HTMLButtonElement>(null);
  const fullButtonRef = useRef<HTMLButtonElement>(null);
  const iconOnlyButtonRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!containerRef?.current || dimensions) {
      return;
    }

    const measureButtons = () => {
      if (!fullButtonRef.current || !iconOnlyButtonRef.current) {
        return;
      }

      const fullButtonWidth = fullButtonRef.current.offsetWidth;
      const iconButtonWidth = iconOnlyButtonRef.current.offsetWidth;

      setDimensions({ fullWidth: fullButtonWidth, iconWidth: iconButtonWidth });
    };

    measureButtons();
  }, [containerRef, dimensions]);

  useEffect(() => {
    if (!containerRef?.current || !dimensions || jsdomMode) {
      return;
    }

    const container = containerRef.current;

    const checkButtonFit = () => {
      const containerWidth = container.offsetWidth;
      const containerHeight = container.offsetHeight;

      if (dimensions.fullWidth <= containerWidth && containerHeight >= 50) {
        setButtonMode('full');
      } else if (dimensions.iconWidth <= containerWidth && containerHeight >= 40) {
        setButtonMode('icon-only');
      } else {
        setButtonMode('hidden');
      }
    };

    checkButtonFit();

    const resizeObserver = new ResizeObserver(() => {
      checkButtonFit();
    });

    resizeObserver.observe(container);

    return () => {
      resizeObserver.disconnect();
    };
  }, [containerRef, dimensions, jsdomMode]);

  return (
    <div
      className={classes.addCaptionButtonContainer}
      contentEditable={false}
      suppressContentEditableWarning
    >
      {!dimensions && (
        <div
          style={{ position: 'absolute', visibility: 'hidden', top: '-9999px' }}
          aria-hidden="true"
          role="presentation"
        >
          <CaptionButtonContent ref={fullButtonRef} isIconOnly={false} />
          <CaptionButtonContent ref={iconOnlyButtonRef} isIconOnly />
        </div>
      )}

      {(() => {
        switch (buttonMode) {
          case 'full':
            return (
              <CaptionButtonContent
                ref={buttonRef}
                onAddCaption={onAddCaption}
                isIconOnly={false}
              />
            );
          case 'icon-only':
            return (
              <Tooltip content={t('Figure_Caption_AddButton_Title')} size="small">
                <CaptionButtonContent ref={buttonRef} onAddCaption={onAddCaption} isIconOnly />
              </Tooltip>
            );
          case 'hidden':
            return null;
          default:
            return null;
        }
      })()}
    </div>
  );
};
