import type { ModalService } from './../../ricos-modals/index.js';
import type { Modal, Placement } from './../../ricos-types/index.js';
import type { NamedLink } from './../link/types.js';

import { LINK_MODAL_ID } from './constants.js';
import { openLinkModal } from './open-link-modal.js';
import type { LinkType } from './open-link-modal/types.js';

export const toggleLinkModal = ({
  initialValue,
  modalService,
  onSave,
  onSaveMultiple,
  onUnlink,
  referenceElement,
  placement,
  onClickOutside,
  returnFocusToEditor,
  enabledLinkTypes,
  showAltText,
  initialAltText,
}: {
  initialValue?: NamedLink | undefined;
  modalService: ModalService;
  onSave: (linkData: NamedLink, altText?: string) => void;
  onUnlink: (linkData: NamedLink) => void;
  onSaveMultiple?: (links: NamedLink[]) => void;
  referenceElement?: HTMLElement | null;
  placement?: Placement;
  onClickOutside?: Modal['onClickOutside'];
  returnFocusToEditor?: boolean;
  enabledLinkTypes?: LinkType[];
  showAltText?: boolean;
  initialAltText?: string;
}) =>
  modalService.isModalOpen(LINK_MODAL_ID)
    ? modalService.closeModal(LINK_MODAL_ID)
    : openLinkModal({
        initialValue,
        modalService,
        onSaveMultiple,
        onSave,
        onUnlink,
        referenceElement,
        placement,
        onClickOutside,
        returnFocusToEditor,
        enabledLinkTypes,
        showAltText,
        initialAltText,
      });
