import React from 'react';

import type { PluginProps } from './../../ricos-types/index.js';
import type { Editor } from './../../tiptap/core/index.js';
import { NodeSelection } from './../../tiptap/pm/state.js';

import classes from './overlay-hoc-scss.js';

type OverlayProps = {
  disabled?: boolean;
};

export const OverlayHoc = <P extends PluginProps>(
  Component: React.ComponentType<P>
): React.ComponentType<P & OverlayProps> => {
  const Overlay = (props: P & OverlayProps) => {
    const { disabled } = props;

    return (
      <div
        className={disabled ? undefined : classes.overlay}
        role="none"
        onClick={() => {
          if (!disabled) {
            setSelection((props as P).editor, (props as P).getPos);
          }
        }}
      >
        <Component {...(props as P)} />
      </div>
    );
  };
  Overlay.displayName = 'OverlayHoc';
  return Overlay;
};

const setSelection = (editor: Editor, getPos: () => number) => {
  const selection = NodeSelection.create(editor.view.state.doc, getPos());
  const transaction = editor.view.state.tr.setSelection(selection);
  editor.view.dispatch(transaction);
};
