import { parse } from 'svgson';

import type { FileSource } from './../../ricos-schema/next-schema/index.js';

import { getShapeUrl } from './get-shape-url.js';

export const getParsedShape = async (
  shapeSrc: FileSource,
  getUrlOverride?: () => string | undefined
) => {
  try {
    const shapeUrl = getShapeUrl(shapeSrc, getUrlOverride);

    const svgJson = await fetch(shapeUrl)
      .then(res => res.text())
      .then(text => parse(text));

    return svgJson;
  } catch (error) {
    console.error('[ShapeService] Failed to fetch shapes:', error);
    throw error;
  }
};
