import { TIPTAP_COLLAPSIBLE_LIST_TYPE } from './../../ricos-content/consts.js';
import type { Resolver } from './../../ricos-types/index.js';
import { findParentNodeClosestToPos } from './../../tiptap/index.js';
import type { Node } from './../../tiptap/pm/model.js';

export const getCollapsibleListInSelection: Resolver<Node | undefined> = (_, __, editor) => {
  const selection = editor?.state?.selection;

  if (!selection) {
    return undefined;
  }

  return findParentNodeClosestToPos(
    selection?.$to,
    node => node?.type?.name === TIPTAP_COLLAPSIBLE_LIST_TYPE
  )?.node;
};
