import type { NodeWithPos } from './../tiptap/index.js';
import { findParentNodeClosestToPos } from './../tiptap/index.js';
import type { Editor } from './../tiptap/core/index.js';

export type ToolbarReferenceElementOptions = {
  handleSelector: string;
  containerSelector?: string;
  topOffset?: number;
  bottomOffset?: number;
  nodeType?: string;
};

export const getToolbarReferenceElement = (
  tiptapEditor: Editor,
  options: ToolbarReferenceElementOptions
): { getBoundingClientRect: () => DOMRect; contextElement: HTMLElement } | HTMLElement | null => {
  const closest: NodeWithPos | undefined = findParentNodeClosestToPos(
    tiptapEditor.state.selection.$from,
    node => node.type.name === options.nodeType
  );
  const startNodePos = closest
    ? tiptapEditor.$pos(closest.pos)
    : tiptapEditor.state.selection.$from;
  const nodeElement = tiptapEditor.view.nodeDOM(startNodePos.pos) as HTMLElement | null;

  const handleElement = nodeElement?.querySelector?.(options.handleSelector);

  if (nodeElement && handleElement) {
    return {
      getBoundingClientRect: () => {
        const containerElement = options.containerSelector
          ? (nodeElement.querySelector(options.containerSelector) ??
            nodeElement.closest(options.containerSelector) ??
            nodeElement)
          : nodeElement;
        const nodeElementRect = containerElement?.getBoundingClientRect();
        const borderTopWidth = parseInt(
          getComputedStyle(containerElement).getPropertyValue('border-top-width')
        );
        const handleElementRect = handleElement?.getBoundingClientRect();
        return new DOMRect(
          nodeElementRect.x,
          Math.min(handleElementRect.y, nodeElementRect.y) +
            (options.topOffset ?? 0) * -1 +
            (isNaN(borderTopWidth) ? 0 : borderTopWidth),
          nodeElementRect.width,
          nodeElementRect.height +
            handleElementRect.height +
            (options.topOffset ?? 0) +
            (options.bottomOffset ?? 0)
        );
      },
      contextElement: nodeElement,
    };
  }

  return tiptapEditor.view.nodeDOM(startNodePos.pos - 1) as HTMLElement | null;
};
