import type { MediaItem } from '@wix/ambassador-media-public-media-v1-media-item/types';
import { Tabs } from '@wix/design-system';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { Panel, PanelHeader } from './../../ui-components/index.js';

import { ICONS_CATEGORY_ID, SHAPES_CATEGORY_ID, VECTOR_ART_CATEGORY_ID } from './consts.js';
import { SHAPE_SELECT_MODAL } from './data-hooks.js';
import { ShapeSelectModalContent } from './shape-select-modal-content.js';
import type { ShapesCategoryId } from './types.js';

type Props = {
  onShapeSelect: (shape: MediaItem) => void | Promise<void>;
  onClose: () => void;
  allowedCategoryIds?: readonly [ShapesCategoryId, ...ShapesCategoryId[]];
  initialCategoryId?: ShapesCategoryId;
};

const DEFAULT_ALLOWED_CATEGORY_IDS = [
  SHAPES_CATEGORY_ID,
  VECTOR_ART_CATEGORY_ID,
  ICONS_CATEGORY_ID,
] as const;

export const ShapeSelectModal = ({
  onShapeSelect,
  onClose,
  allowedCategoryIds,
  initialCategoryId,
}: Props) => {
  const { t, isMobile } = useContext(RicosContext);
  const categoryIds = allowedCategoryIds ?? DEFAULT_ALLOWED_CATEGORY_IDS;
  const [selectedCategoryId, setSelectedCategoryId] = useState<ShapesCategoryId>(
    initialCategoryId && categoryIds.includes(initialCategoryId)
      ? initialCategoryId
      : categoryIds[0]
  );

  const categoryItems = categoryIds.map(id => ({
    id,
    title:
      id === SHAPES_CATEGORY_ID
        ? t('ShapeSelectModal_Tab_Shapes')
        : id === VECTOR_ART_CATEGORY_ID
          ? t('ShapeSelectModal_Tab_VectorArt')
          : t('ShapeSelectModal_Tab_Icons'),
  }));

  return (
    <Panel
      closeButtonProps={{ onClick: onClose }}
      width={isMobile ? '100%' : 430}
      height={isMobile ? '100%' : 576}
    >
      <PanelHeader title={t('ShapeSelectModal_Header_Title')} />

      <div data-hook={SHAPE_SELECT_MODAL}>
        {categoryItems.length > 1 && (
          <Tabs
            size="small"
            alignment="center"
            type="uniformFull"
            minWidth={0}
            activeId={selectedCategoryId}
            onClick={value => setSelectedCategoryId(value.id as ShapesCategoryId)}
            items={categoryItems}
          />
        )}

        <ShapeSelectModalContent
          onShapeSelect={onShapeSelect}
          selectedCategoryId={selectedCategoryId}
        />
      </div>
    </Panel>
  );
};
