import type { MediaItem } from '@wix/ambassador-media-public-media-v1-media-item/types';
import { Box, Image, Loader, Search } from '@wix/design-system';
import React, { useContext, useEffect, useRef, useState } from 'react';
import InfiniteScroll from 'react-infinite-scroller';

import { RicosContext, useDevShapeService } from './../../ricos-context/index.js';
import { useBiNext } from './../bi-context-provider/bi-context-provider.js';
import { useRequestService } from './../request-service-provider/request-service-provider.js';
import { uuid } from './../../wix-rich-content-common/index.js';

import { ICONS_CATEGORY_ID, SEARCH_DEBOUNCE_MS, SHAPES_CATEGORY_ID } from './consts.js';
import {
  SHAPE_SELECT_MODAL,
  SHAPE_SELECT_MODAL_CONTENT,
  SHAPE_SELECT_MODAL_CONTENT_ITEM,
  SHAPE_SELECT_MODAL_SEARCH_INPUT,
} from './data-hooks.js';
import { ShapeSelectEmpty } from './shape-select-empty.js';
import styles from './shape-select-modal-content-scss.js';
import { fetchShapes } from './shape-service.js';
import type { ShapesCategoryId, ShapesState } from './types.js';

type Props = {
  onShapeSelect: (shape: MediaItem) => void | Promise<void>;
  selectedCategoryId: ShapesCategoryId;
};

const TILE_HEIGHT = 83;
const TILE_BORDER_RADIUS = '8px';
const SCROLL_AREA_HEIGHT = 414;
const MOBILE_SCROLL_AREA_HEIGHT = 'calc(100vh - 190px)';
/** Tiles fade in only once their image has decoded, so the placeholder is not seen through. */
const PENDING_TILE_STYLE = { opacity: 0 };

export const ShapeSelectModalContent = ({ onShapeSelect, selectedCategoryId }: Props) => {
  const { makeRequest } = useRequestService();
  const { t, isMobile } = useContext(RicosContext);
  const devShapeService = useDevShapeService();
  const logBi = useBiNext({ modalId: SHAPE_SELECT_MODAL, pluginId: 'shape' });
  const requestIdRef = useRef<string>('');
  const isDevEnv = !!devShapeService?.fetchShapes;

  const [state, setState] = useState<ShapesState>({
    type: 'LOADING',
    searchString: '',
  });
  const [loadedImages, setLoadedImages] = useState<Set<string>>(new Set());

  useEffect(() => {
    requestIdRef.current = uuid();

    setState({
      type: 'LOADING',
      searchString: '',
    });

    setLoadedImages(new Set());

    loadShapesData({ page: 1, searchString: '', requestId: requestIdRef.current });
  }, [selectedCategoryId]);

  const loadShapesData = async ({
    page,
    searchString,
    requestId,
  }: {
    page: number;
    searchString: string;
    requestId: string;
  }) => {
    try {
      const fetchShapesFn = devShapeService?.fetchShapes ?? fetchShapes;

      const response = await fetchShapesFn(
        {
          cursor: {
            limit: 50,
            cursor: String(page),
          },
          searchString,
          searchCategories: [
            {
              categoryId: selectedCategoryId,
            },
          ],
        },
        makeRequest
      );

      const shapeItems = response.categoryResults?.[0]?.items || [];

      if (!requestIdRef.current || requestIdRef.current === requestId) {
        setState(prev => {
          const prevItems = prev.type === 'LOADING' || prev.type === 'ERROR' ? [] : prev.items;

          return {
            type: 'LOADED',
            items: page === 1 ? shapeItems : [...prevItems, ...shapeItems],
            hasMore: !isDevEnv ? !!shapeItems.length : false,
            page,
            searchString,
          };
        });
      }
    } catch {
      setState({
        type: 'ERROR',
      });
    }
  };

  const onShapeKeyDown = (e: React.KeyboardEvent<HTMLImageElement>, shape: MediaItem) => {
    if (['Enter', ' '].includes(e.key)) {
      onShapeSelect(shape);
    }
  };

  const onImageLoad = (imageId: string) => {
    setLoadedImages(prev => new Set(prev).add(imageId));
  };

  const onSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    logBi({
      dataHook: SHAPE_SELECT_MODAL_SEARCH_INPUT,
      value: e.target.value,
    });

    requestIdRef.current = uuid();

    loadShapesData({ page: 1, searchString: e.target.value, requestId: requestIdRef.current });

    setState({
      type: 'LOADING',
      searchString: e.target.value,
    });

    setLoadedImages(new Set());
  };

  const onSearchClear = () => {
    requestIdRef.current = uuid();

    setState({
      type: 'LOADING',
      searchString: '',
    });

    loadShapesData({ page: 1, searchString: '', requestId: requestIdRef.current });
  };

  const onInfiniteScrollLoadMore = async () => {
    if (state.type !== 'LOADED') {
      return;
    }

    const nextPage = state.page + 1;

    requestIdRef.current = uuid();

    setState({
      type: 'LOADING_MORE',
      items: state.items,
      page: nextPage,
      searchString: state.searchString,
    });

    await loadShapesData({
      page: nextPage,
      searchString: state.searchString,
      requestId: requestIdRef.current,
    });
  };

  const searchString = state.type === 'ERROR' ? '' : state.searchString;
  const items = state.type === 'LOADED' || state.type === 'LOADING_MORE' ? state.items : [];
  const hasMore = state.type === 'LOADED' ? state.hasMore : false;

  return (
    <Box direction="vertical">
      <Box padding="SP3">
        <Search
          dataHook={SHAPE_SELECT_MODAL_SEARCH_INPUT}
          placeholder={
            selectedCategoryId === SHAPES_CATEGORY_ID
              ? t('ShapeSelectModalContent_Search_Placeholder')
              : selectedCategoryId === ICONS_CATEGORY_ID
                ? t('ShapeSelectModalContent_Search_Placeholder_Icons')
                : t('ShapeSelectModalContent_Search_Placeholder_VectorArt')
          }
          onChange={onSearchChange}
          onClear={onSearchClear}
          debounceMs={SEARCH_DEBOUNCE_MS}
          value={searchString}
        />
      </Box>

      {/*
        This is the scrollport `react-infinite-scroller` measures against, so it must stay the
        direct parent of the grid below: the scroller reads `scrollTop`/`clientHeight` off
        `scrollComponent.parentNode`. `display: block` keeps `Box`'s flex root from shrinking
        the grid to the fixed height instead of letting it overflow and scroll.
      */}
      <Box
        dataHook={SHAPE_SELECT_MODAL_CONTENT}
        display="block"
        height={isMobile ? MOBILE_SCROLL_AREA_HEIGHT : SCROLL_AREA_HEIGHT}
        overflow="auto"
        padding="0px 16px 16px"
      >
        {state.type === 'LOADING' && (
          <Box height="100%" align="center" verticalAlign="middle">
            <Loader size="small" />
          </Box>
        )}

        {state.type === 'ERROR' && (
          <ShapeSelectEmpty isError selectedCategoryId={selectedCategoryId} />
        )}

        {state.type === 'LOADED' && !state.items.length && state.searchString && (
          <ShapeSelectEmpty selectedCategoryId={selectedCategoryId} />
        )}

        <InfiniteScroll
          className={styles.shape_select_modal_content_infinite_scroll}
          initialLoad={false}
          loadMore={onInfiniteScrollLoadMore}
          hasMore={hasMore}
          useWindow={false}
          loader={
            state.type === 'LOADING_MORE' && (
              <Box
                gridColumn="1 / -1"
                align="center"
                verticalAlign="middle"
                margin="20px 0px"
                padding="20px"
              >
                <Loader size="small" />
              </Box>
            )
          }
        >
          {items.map(({ item }) => {
            const shapeId = item?.id;

            if (!item || !shapeId) {
              return null;
            }

            const isImageLoaded = loadedImages.has(shapeId);

            return (
              <Box key={shapeId} position="relative" height={TILE_HEIGHT}>
                {!isImageLoaded && (
                  <Box
                    position="absolute"
                    top={0}
                    right={0}
                    bottom={0}
                    left={0}
                    zIndex={1}
                    align="center"
                    verticalAlign="middle"
                    backgroundColor="rgba(0, 6, 36, 0.1)"
                    borderRadius={TILE_BORDER_RADIUS}
                  >
                    <Loader size="tiny" />
                  </Box>
                )}
                <Image
                  data-id={shapeId}
                  tabIndex={0}
                  transparent
                  onKeyDown={e => onShapeKeyDown(e, item)}
                  onClick={() => onShapeSelect(item)}
                  onLoad={() => onImageLoad(shapeId)}
                  dataHook={SHAPE_SELECT_MODAL_CONTENT_ITEM}
                  id={shapeId}
                  role="img"
                  aria-label="Shape"
                  fit="contain"
                  height={TILE_HEIGHT}
                  src={item.assets?.vector?.image?.url || ''}
                  className={styles.shape_select_modal_content_shape_img_container}
                  style={isImageLoaded ? undefined : PENDING_TILE_STYLE}
                  showBorder
                  borderRadius={TILE_BORDER_RADIUS}
                  alt={item.title || ''}
                />
              </Box>
            );
          })}
        </InfiniteScroll>
      </Box>
    </Box>
  );
};
