import type { PluginContainerData_Width_Type } from './../../ricos-schema/next-schema/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const getNodeSize: Resolver<PluginContainerData_Width_Type | undefined> = (
  _,
  __,
  editor
) => {
  const node = (editor?.state?.selection as Record<string, any> | undefined)?.node;
  if (node) {
    return node.attrs?.containerData?.width?.size;
  }
  return undefined;
};
