const getAbsoluteUrl = (url: string) =>
  url.substring(0, 5).includes('http') ? url : 'http://' + url;

const buildUrl = (videoUrl: string) => {
  const baseUrl =
    typeof location !== 'undefined' && location.hostname === 'editor.wix.com'
      ? 'https://editor.wix.com/rich-content/oembed'
      : 'https://www.wixapis.com/ricos/v1/oembeds';
  const url = new URL(baseUrl);
  url.searchParams.append('url', getAbsoluteUrl(videoUrl));
  url.searchParams.append('options.maxWidth', '980');
  return url;
};

export const fetchOembed = async (url: string, instance: string) => {
  const res = await fetch(buildUrl(url), {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      Authorization: instance,
    },
  });
  return res.json();
};

// TODO: merge this function with fetchOembed when all of the strategies are moved out of WixRicosEditor into their plugins
export const fetchOembedWithAuth = async (
  url: string,
  makeRequest: (input: string | URL, init?: RequestInit) => Promise<Response>
) => {
  const res = await makeRequest(buildUrl(url), {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
    },
  });

  return res.json();
};

const providerBlackList = ['wix', 'facebook'];

export const fetchEmbedData = (instance: string) => async (url: string) => {
  try {
    return fetchOembed(url, instance).then(json => {
      const { html, ...rest } = json;
      const { provider_name } = rest;
      const res = providerBlackList.includes((provider_name || '').toLowerCase())
        ? { ...rest }
        : { ...rest, html };
      return res;
    });
  } catch {
    return new Promise(resolve => {
      setTimeout(() => resolve({}), 1);
    });
  }
};
