import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const isLinkPreviewEnabled: Resolver<boolean> = (content, _services, editor) => {
  if (editor?.commands.createLinkPreview) {
    const node = content.find(node => node.type.name === 'text');
    const linkMark = node?.marks.find(mark => mark.type.name === Decoration_Type.LINK);

    if (!linkMark) {
      return false;
    }

    return !!linkMark.attrs?.link?.url;
  }
  return false;
};
