import type { ComponentType, FC, PropsWithChildren } from 'react';
import React, { useMemo, useState } from 'react';

import type { RicosEditorAPI } from './../../ricos-types/index.js';
import { createContext, useContextSelector } from './../use-context-selector.js';

type RicosEditorApiContextValue = {
  ricosEditorApi: RicosEditorAPI | null;
  setRicosEditorApi: (api: RicosEditorAPI | null) => void;
};

const noopSetter = (_api: RicosEditorAPI | null) => {};

export const RicosEditorApiContext = createContext<RicosEditorApiContextValue>({
  ricosEditorApi: null,
  setRicosEditorApi: noopSetter,
});

/**
 * Provides a context slot for sharing the imperative `RicosEditor` API with
 * descendants. The wrapped `RicosEditor` self-registers into this slot on
 * mount, so descendants can read it via `useRicosEditorApi()` without prop
 * drilling or rolling their own context.
 *
 * **The provider must wrap exactly one `<RicosEditor>` underneath. Two or
 * more editors will race on the shared slot — the last to mount wins, and
 * the context will silently point at the wrong instance. Or the sky will
 * fall.**
 */
export const RicosEditorApiProvider: FC<PropsWithChildren> = ({ children }) => {
  const [ricosEditorApi, setRicosEditorApi] = useState<RicosEditorAPI | null>(null);
  const value = useMemo(() => ({ ricosEditorApi, setRicosEditorApi }), [ricosEditorApi]);
  return <RicosEditorApiContext.Provider value={value}>{children}</RicosEditorApiContext.Provider>;
};

/**
 * Returns the current `RicosEditorAPI` from the nearest `RicosEditorApiProvider`,
 * or `null` if no provider is mounted or the editor has not finished mounting yet.
 *
 * Selector-based subscription — only re-renders when the API instance itself
 * changes (`null` → instance, instance → `null`).
 */
export const useRicosEditorApi = (): RicosEditorAPI | null =>
  useContextSelector(RicosEditorApiContext, c => c.ricosEditorApi, Object.is);

/** @internal — used by `<RicosEditor>` to register itself into the context. */
export const useSetRicosEditorApi = (): ((api: RicosEditorAPI | null) => void) =>
  useContextSelector(RicosEditorApiContext, c => c.setRicosEditorApi, Object.is);

/**
 * HOC that injects the current `RicosEditorAPI` (or `null`) as an `editor`
 * prop. Useful when migrating class components off the legacy
 * `withEditorContext` HOC.
 */
export const withRicosEditorApi = <P extends object>(
  Component: ComponentType<P & { editor: RicosEditorAPI | null }>
): FC<P> => {
  const Wrapped: FC<P> = props => {
    const editor = useRicosEditorApi();
    return <Component {...(props as P)} editor={editor} />;
  };
  Wrapped.displayName = `withRicosEditorApi(${Component.displayName ?? Component.name ?? 'Component'})`;
  return Wrapped;
};
