import type { IEditorQuery } from './../../ricos-content-query/types.js';
import type { Resolver } from './../../ricos-types/index.js';

import { getTextAlignment } from '../get-text-alignment.js';

export const isTextAlignedCenter: Resolver<boolean> = (_content, { getEditorQuery }, editor) => {
  const editorQuery: IEditorQuery = getEditorQuery();
  const activeTextStyles = editorQuery.query.activeTextStyles('textAlignment');
  if (editor && activeTextStyles.length > 0 && [...new Set(activeTextStyles)].length === 1) {
    return getTextAlignment(activeTextStyles[0], editor) === 'center';
  }
  return false;
};
