import type { Animation } from './../../ricos-schema/next-schema/index.js';

/**
 * Whether this animation participates in the reveal contract: only nodes with an
 * entrance are SSR-hidden until played (`data-ricos-entrance` marker → hide CSS in
 * node-animations.tsx). A loop-only node must stay visible from first paint — it
 * animates in place, and hiding it would gate content on a decoration.
 */
export const hasEntranceAnimation = (animation: Animation | undefined): boolean =>
  animation?.type === 'VIEW' && Boolean(animation.entrance?.effect);
