import type { ObjectPath } from './path-to-segments.js';
import { hasUnsafePathSegment, pathToSegments } from './path-to-segments.js';

// Reads a nested value by a lodash-style path (array of keys or 'a.b[0].c'
// string). Used where paths are only known at runtime (TranslatableAPI, velo
// adapter); statically-known paths should use optional chaining instead. The
// generic defaults to `any` to mirror lodash.get, since a dynamic path can't be
// statically typed — pass an explicit type argument when the shape is known.
// oxlint-disable-next-line @typescript-eslint/no-explicit-any
export function getByPath<T = any>(obj: unknown, path: ObjectPath, defaultValue?: T): T {
  const segments = pathToSegments(path);
  // Never resolve through prototype keys — returning e.g. Object.prototype
  // methods for a '__proto__.*' path would leak realm internals and (paired
  // with a write) enable prototype-pollution gadgets.
  if (hasUnsafePathSegment(segments)) {
    return defaultValue as T;
  }
  let current: unknown = obj;
  for (const segment of segments) {
    if (current === null || current === undefined) {
      return defaultValue as T;
    }
    current = (current as Record<PropertyKey, unknown>)[segment];
  }
  return (current === undefined ? defaultValue : current) as T;
}
