import { type EditorState, NodeSelection } from './../tiptap/pm/state.js';

/**
 * Returns `true` if node with the provided id is the only node within the current selection range.
 */
export const isOnlyNodeSelected = (state: EditorState, nodeId: string) => {
  if (state.selection instanceof NodeSelection) {
    return state.selection.node.attrs.id === nodeId;
  }

  return false;
};
