import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const isLinkInLinkPreview: Resolver<boolean> = content => {
  if (Array.isArray(content)) {
    const node = content.find(node => {
      return node.type.name === Node_Type.LINK_PREVIEW;
    });

    const url = node?.attrs?.link?.url;
    return typeof url === 'string' && url !== '';
  }
  return false;
};
