import type { Gradient } from './../ricos-types/color-palette-types.js';
import type { RicosPalette } from './../ricos-types/index.js';

import { hexToRgba } from '../theme-utils/color-utils.js';
import { resolveDocumentColorToHex } from './theme-color-token.js';

const resolveStopColor = (color: string | undefined, palette?: RicosPalette): string | undefined =>
  palette && color ? (resolveDocumentColorToHex(color, palette) ?? color) : color;

const formatStop = (
  stop: NonNullable<Gradient['stops']>[number],
  palette?: RicosPalette
): string => {
  const color = resolveStopColor(stop.color, palette);
  const position = ((stop.position ?? 0) * 100).toFixed(2);
  return `${hexToRgba(color)} ${position}%`;
};

const formatStops = (stops: Gradient['stops'], palette?: RicosPalette): string =>
  [...(stops ?? [])]
    .filter(stop => stop.color)
    .sort((a, b) => (a.position ?? 0) - (b.position ?? 0))
    .map(stop => formatStop(stop, palette))
    .join(', ');

// Pass a palette when the CSS is consumed by FillPreview, whose gradient parser
// cannot parse CSS var based gradient stops like rgba(var(--color), 0.5).
export const schemaGradientToCss = (gradient?: Gradient, palette?: RicosPalette): string => {
  if (!gradient) {
    return '';
  }

  if (gradient.type === 'LINEAR') {
    return `linear-gradient(${gradient.angle ?? 90}deg, ${formatStops(gradient.stops, palette)})`;
  }

  if (gradient.type === 'RADIAL') {
    return `radial-gradient(circle at ${gradient.centerX ?? 50}% ${gradient.centerY ?? 50}%, ${formatStops(gradient.stops, palette)})`;
  }

  return '';
};
