import { getTextDirection } from './../ricos-content/index.js';
import type { Editor } from './../tiptap/core/index.js';

type EditorQueryTextAlignment = 'LEFT' | 'CENTER' | 'RIGHT' | 'JUSTIFY' | 'AUTO';

export const getTextAlignment = (activeTextAlignment: EditorQueryTextAlignment, editor: Editor) => {
  const textAlignment = activeTextAlignment.toLowerCase();
  if (textAlignment !== 'auto') {
    return textAlignment;
  }
  const {
    state: {
      doc,
      selection: { from },
    },
  } = editor;

  const nodeToCheck = doc.nodeAt(from);
  const isTextNode = nodeToCheck?.type.name === 'text';
  const isEmptyLine = nodeToCheck?.type.name === undefined;
  if (!(isTextNode || isEmptyLine)) {
    return;
  }

  const selectedFirstNodeText = doc.nodeAt(from - 1)?.textContent;
  const selectedFirstNodeDirection = getTextDirection(selectedFirstNodeText);
  return selectedFirstNodeDirection === 'rtl' ? 'right' : 'left';
};
