import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const isQuoteInSelection: Resolver<boolean> = content => {
  if (Array.isArray(content)) {
    const node = content.find(node => node.type.name === Node_Type.BLOCKQUOTE);
    return Boolean(node);
  }

  return false;
};
