import { Decoration_Type } from './../../ricos-types/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const isLinkOrAnchorInText: Resolver<boolean> = content => {
  if (Array.isArray(content)) {
    const node = content.find(node => {
      return node.type.name === 'text';
    });
    return (
      node?.marks.some(
        mark => mark.type.name === Decoration_Type.LINK || mark.type.name === Decoration_Type.ANCHOR
      ) ?? false
    );
  }
  return false;
};
