import { findChildren } from './../../tiptap/helpers/index.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import type { EditorView as ProseMirrorEditorView } from './../../tiptap/pm/view.js';

export const getDomAtPosOrParent = (
  doc: ProseMirrorNode,
  view: ProseMirrorEditorView,
  from: number
): HTMLElement | undefined => {
  try {
    const domAtCurrentPos = view.nodeDOM(from) as HTMLElement | null;
    let element: HTMLElement | null | undefined;

    if (domAtCurrentPos) {
      element = domAtCurrentPos;
    } else {
      // Try domAtPos — returns position inside actual content (not nodeView wrapper).
      // This is critical for nodes rendered as React nodeViews (e.g. caption),
      // where view.nodeDOM returns the wrapper above the styled element.
      try {
        const { node } = view.domAtPos(from);
        element = node instanceof HTMLElement ? node : node.parentElement;
      } catch {
        // domAtPos can throw for positions outside the document
      }

      // Last resort: find parent by ID and use nodeDOM
      if (!element) {
        const parent = doc.resolve(from).parent;
        const parentNodeWithPos = findChildren(doc, node => node.attrs.id === parent.attrs.id)[0];

        if (parentNodeWithPos) {
          element = view.nodeDOM(parentNodeWithPos.pos) as HTMLElement;
        }
      }
    }

    if (!element) {
      return undefined;
    }

    const elementToReturn = element.nodeType === Node.TEXT_NODE ? element.parentElement : element;
    return (elementToReturn as HTMLElement) ?? undefined;
  } catch (e: any) {
    console.error('Failed to get parent node:', e);
    return undefined;
  }
};
