import type { IEditorQuery } from './../../ricos-content-query/index.js';
import type { Decoration } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type } from './../../ricos-types/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const isStrikethroughInText: Resolver<boolean> = (content, { getEditorQuery }, _editor) => {
  const editorQuery: IEditorQuery = getEditorQuery();
  const decorations: Decoration[] = editorQuery.query.activeDecorationsByType(
    Decoration_Type.STRIKETHROUGH
  );
  return (
    decorations.length > 0 &&
    decorations.every(item => item?.type === Decoration_Type.STRIKETHROUGH)
  );
};
